package com.talentallocation.backend.model;

import jakarta.persistence.*;
import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.AllArgsConstructor;
import java.time.LocalDateTime;

/**
 * Represents a training recommendation for an employee to develop a missing skill.
 * Generated by the AI staffing agent based on skill gaps.
 */
@Entity
@Table(name = "training_recommendations",
    indexes = {
        @Index(name = "idx_tr_employee", columnList = "employee_id"),
        @Index(name = "idx_tr_skill", columnList = "skill_id"),
        @Index(name = "idx_tr_status", columnList = "status")
    }
)
@Data
@NoArgsConstructor
@AllArgsConstructor
public class TrainingRecommendation {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "employee_id", nullable = false)
    private Employee employee;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "skill_id", nullable = false)
    private Skill skill;

    @Column(nullable = false, length = 1000)
    private String reason;

    @Column(length = 1000)
    private String learningPath;

    @Column(length = 200)
    private String relatedDemandRole;

    @Column(nullable = false)
    @Enumerated(EnumType.STRING)
    private TrainingStatus status;

    @Column(nullable = false, updatable = false)
    private LocalDateTime createdAt;

    @PrePersist
    protected void onCreate() {
        createdAt = LocalDateTime.now();
        if (status == null) {
            status = TrainingStatus.RECOMMENDED;
        }
    }

    public enum TrainingStatus {
        RECOMMENDED, IN_PROGRESS, COMPLETED, DISMISSED
    }
}
